// minimal Howler shim - pakai HTML5 Audio biar gak butuh CDN
window.Howl = function(opts){
  this.src = opts.src[0];
  this.audio = new Audio(this.src);
  this.play = ()=>{ this.audio.currentTime=0; this.audio.play().catch(()=>{}); };
  this.stop = ()=>{ this.audio.pause(); this.audio.currentTime=0; };
};
window.Howler = {volume:()=>{}};
